insert into public.rule_sources(id,data) values('demo','{"id":"demo","organisation":"WAYPOINT demonstration team","title":"Fictional trade-preparation rule specification","reference":"WAYPOINT-DEMO-2026-09","jurisdiction":"NG / GH / KE","checked":"2026-09-12","notes":"DEMO / NOT FOR COMMERCIAL USE. These are authored test fixtures, not official legal requirements. Tariffs are not configured."}'::jsonb) on conflict do nothing;
insert into public.rule_packs(id,version,data) values('CORE','1.0','{"id":"CORE","name":"Shipment preparation foundation","country":"ALL","version":"1.0","published":"2026-09-12","status":"published","rules":[{"version":"1.0","country":"ALL","direction":"all","category":"all","when":{"all":[]},"severity":"blocker","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"product","title":"Complete product and shipment information","stage":"Product","check":{"field":"valid","op":"equals","value":true},"message":"Complete product and shipment information within the configured demonstration rules.","resolution":"Complete the missing information and recompile."},{"version":"1.0","country":"ALL","direction":"all","category":"all","when":{"all":[]},"severity":"review","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"classification","title":"Classification confirmed","stage":"Classification","check":{"all":[{"field":"classification","op":"exists"},{"field":"confirmed","op":"equals","value":true}]},"message":"A candidate classification must be confirmed by the exporter or a professional.","resolution":"Review the classification and confirm it, or request a consultant."},{"version":"1.0","country":"ALL","direction":"all","category":"all","when":{"all":[]},"severity":"blocker","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"invoice","title":"Commercial invoice available","stage":"Export requirements","check":{"field":"docs.invoice","op":"equals","value":true},"message":"Commercial invoice available within the configured demonstration rules.","resolution":"Upload a commercial invoice.","documentType":"invoice"},{"version":"1.0","country":"ALL","direction":"all","category":"all","when":{"all":[]},"severity":"review","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"origin","title":"Manufacturing origin supported","stage":"Rules of origin","check":{"field":"originSimple","op":"equals","value":true},"message":"Demo origin check: manufacture and export countries match, with at least 60% declared local content. This is a fictional threshold, not an AfCFTA origin determination.","resolution":"Provide manufacturing evidence and ask a consultant to review complex origin."},{"version":"1.0","country":"ALL","direction":"all","category":"all","when":{"all":[]},"severity":"warning","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"transport","title":"Transport document available","stage":"Transport","check":{"field":"docs.transport","op":"equals","value":true},"message":"Transport document available within the configured demonstration rules.","resolution":"Add the transport document when the carrier issues it.","documentType":"transport"},{"version":"1.0","country":"ALL","direction":"all","category":"all","when":{"all":[]},"severity":"blocker","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"packing","title":"Packing list available","stage":"Customs preparation","check":{"field":"docs.packing","op":"equals","value":true},"message":"Packing list available within the configured demonstration rules.","resolution":"Upload a packing list.","documentType":"packing"},{"version":"1.0","country":"ALL","direction":"all","category":"all","when":{"all":[]},"severity":"warning","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"expiry","title":"Documents valid through shipping date","stage":"Customs preparation","check":{"field":"expired","op":"equals","value":false},"message":"Documents valid through shipping date within the configured demonstration rules.","resolution":"Renew documents that expire before the planned shipping date."},{"version":"1.0","country":"ALL","direction":"all","category":"all","when":{"field":"value","op":"gt","value":19999},"severity":"review","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"value","title":"High-value transaction review","stage":"Customs preparation","check":{"field":"value","op":"lt","value":20000},"message":"The fictional demonstration review threshold is USD 20,000 equivalent; currencies other than USD always require review.","resolution":"Ask a consultant to review the valuation."},{"version":"1.0","country":"ALL","direction":"all","category":"all","when":{"all":[]},"severity":"review","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"currency","title":"Currency supported for demo thresholds","stage":"Customs preparation","check":{"field":"currency","op":"equals","value":"USD"},"message":"Currency supported for demo thresholds within the configured demonstration rules.","resolution":"Ask a consultant to review currency conversion and value thresholds."}]}'::jsonb) on conflict do nothing;
insert into public.rule_packs(id,version,data) values('NG-DEMO','1.0','{"id":"NG-DEMO","name":"Nigeria destination pack","country":"NG","version":"1.0","published":"2026-09-12","status":"published","rules":[{"version":"1.0","country":"NG","direction":"destination","category":"all","when":{"all":[]},"severity":"blocker","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"ng-declaration","title":"Destination declaration available","stage":"Destination requirements","check":{"field":"docs.declaration","op":"equals","value":true},"message":"Destination declaration available within the configured demonstration rules.","resolution":"Attach a destination declaration for this demonstration market.","documentType":"declaration"},{"version":"1.0","country":"NG","direction":"destination","category":"all","when":{"all":[]},"severity":"blocker","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"ng-buyer","title":"Destination buyer identified","stage":"Destination requirements","check":{"field":"importer","op":"exists"},"message":"Destination buyer identified within the configured demonstration rules.","resolution":"Complete the missing information and recompile."}]}'::jsonb) on conflict do nothing;
