insert into public.rule_packs(id,version,data) values('KE-DEMO','1.2','{"id":"KE-DEMO","name":"Kenya destination pack","country":"KE","version":"1.2","published":"2026-09-12","status":"published","rules":[{"version":"1.2","country":"KE","direction":"destination","category":"all","when":{"all":[]},"severity":"blocker","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"ke-compliance","title":"Destination product documentation missing","stage":"Destination requirements","check":{"field":"docs.compliance","op":"equals","value":true},"message":"The Kenya demonstration pack requires destination product compliance evidence. This requirement is fictionalised for the demo.","resolution":"Attach the Kenya demo compliance document, or request professional review.","documentType":"compliance"},{"version":"1.0","country":"KE","direction":"destination","category":"all","when":{"all":[]},"severity":"blocker","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"ke-label","title":"Destination labelling information supplied","stage":"Destination requirements","check":{"field":"packaging","op":"exists"},"message":"Destination labelling information supplied within the configured demonstration rules.","resolution":"Complete the missing information and recompile."},{"version":"1.0","country":"KE","direction":"destination","category":"all","when":{"all":[]},"severity":"blocker","sourceId":"demo","effectiveFrom":"2026-01-01","verifiedAt":"2026-09-12","id":"ke-importer","title":"Destination importer identified","stage":"Destination requirements","check":{"field":"importer","op":"exists"},"message":"Destination importer identified within the configured demonstration rules.","resolution":"Complete the missing information and recompile."}]}'::jsonb) on conflict do nothing;
